'use client';

import { Radio } from './components/ui/radio';
import { useId, useState } from 'react';
export default function Example() {
  const name = useId();
  const [course, setCourse] = useState('frontend');
  return <fieldset><legend>참여 분야</legend>{[{ value: 'frontend', label: '프론트엔드' }, { value: 'backend', label: '백엔드' }].map(option => <label key={option.value}><Radio name={name} value={option.value} checked={course === option.value} onChange={event => setCourse(event.currentTarget.value)} />{option.label}</label>)}</fieldset>;
}
